                    ><Render node={option.leading}
                  /></span
                >{:else if option.icon !== undefined
                  }<span class={styles.glyph}><Icon name={option.icon} size="sm" /></span
                >{/if
                }<span class={styles.text}
                  ><span class={styles.label}>{option.label}</span
                  >{#if option.description !== undefined
                    }<span class={styles.description}>{option.description}</span
                  >{/if
                }</span
              ></li
            >{/each
          }</ul
        >{/if
        }{#if loading
          }<div class={styles.rows} aria-hidden="true"
            >{#each [0, 1, 2] as row (row)
              }<div class={styles.row}><Skeleton textStep="sm" /></div
            >{/each
          }</div
        >{/if
        }{#if failed}<div class={styles.error} aria-hidden="true">{source?.error}</div>{/if
        }{#if !loading && !failed && shown.length === 0
          }<div class={styles.empty} aria-hidden="true">{say.noSuggestions}</div
        >{/if
      }</div
    >{/if
    }<div class={styles.status} role="status" aria-live="polite"
      >{#if said.text !== ''}{#key said.at}<span>{said.text}</span>{/key}{/if
    }</div
    >{#if name !== undefined
      }<input type="hidden" {name} value={serializeRichText(doc)} {disabled}
    />{/if
  }</div
>{/if
}{@render joined.end?.()}
